import React, { useState, useEffect, useCallback, useRef } from 'react';
import Lightbox from 'yet-another-react-lightbox';
import 'yet-another-react-lightbox/styles.css';
import { useLanguage } from '../contexts/LanguageContext';

const Gallery = () => {
  const { t } = useLanguage();
  const [images, setImages] = useState([]);
  const [categories, setCategories] = useState(['all']);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const observerTarget = useRef(null);

  // Fetch categories on mount
  useEffect(() => {
    fetchCategories();
  }, []);

  // Fetch images when category changes
  useEffect(() => {
    setImages([]);
    setCurrentPage(1);
    setHasMore(true);
    fetchGalleryImages(1, selectedCategory);
  }, [selectedCategory]);

  // Infinite scroll observer
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !loadingMore) {
          loadMore();
        }
      },
      { threshold: 0.1 }
    );

    if (observerTarget.current) {
      observer.observe(observerTarget.current);
    }

    return () => {
      if (observerTarget.current) {
        observer.unobserve(observerTarget.current);
      }
    };
  }, [hasMore, loadingMore, currentPage, selectedCategory]);

  const fetchCategories = async () => {
    try {
      const response = await fetch('http://127.0.0.1:8000/api/gallery/categories');
      const result = await response.json();
      setCategories(result.categories || ['all']);
    } catch (error) {
      console.error('Error fetching categories:', error);
      setCategories(['all', 'East', 'West', 'North', 'South', 'Central']);
    }
  };

  const fetchGalleryImages = async (page = 1, category = 'all') => {
    try {
      const isFirstPage = page === 1;
      if (isFirstPage) {
        setLoading(true);
      } else {
        setLoadingMore(true);
      }

      // Build URL with pagination and category filter
      const url = new URL('http://127.0.0.1:8000/api/gallery');
      url.searchParams.append('page', page);
      url.searchParams.append('per_page', 24);
      if (category && category !== 'all') {
        url.searchParams.append('category', category);
      }

      const response = await fetch(url);
      const result = await response.json();

      // Laravel paginated response
      const apiData = result.data || [];
      const hasMoreData = result.current_page < result.last_page;

      // Transform API data
      const transformedImages = apiData.map(item => ({
        id: item.id,
        src: item.image_url || item.image_path,
        thumbnail: item.thumbnail_url || item.image_url || item.image_path,
        blurHash: item.blur_hash,
        title: item.title || 'Untitled',
        category: item.category || item.monument?.zone || 'General',
        description: item.description || 'No description available',
      }));

      console.log(`📸 Fetched page ${page}:`, transformedImages.length, 'images');

      if (isFirstPage) {
        setImages(transformedImages);
      } else {
        setImages(prev => [...prev, ...transformedImages]);
      }

      setHasMore(hasMoreData);
      setLoading(false);
      setLoadingMore(false);
    } catch (error) {
      console.error('Error fetching gallery:', error);
      setLoading(false);
      setLoadingMore(false);

      // Fallback to mock data only on first page
      if (page === 1) {
        const mockImages = [
        {
          id: 1,
          src: 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=400',
          title: 'Taj Mahal',
